     'jardineria_corte',  'Corte de grama',              'Corte y nivelación de césped',        '🌱', 300,  18),  ('hogar',     'jardineria_poda',   'Poda de arbustos',            'Poda de arbustos y setos',            '✂️', 450,  19),  ('hogar',     'jardineria_patio',  'Limpieza de patio y jardín',  'Limpieza de patio y áreas verdes',    '🏡', 550,  20),  ('hogar',     'jardineria',        'Riego y mantenimiento',       'Riego y mantenimiento del jardín',    '🌿', 400,  21),  ('hogar',     'pet_care',          'Servicio para mascota',       'Baño y cuidado de mascotas',          '🐕', 250,  22),  ('hogar',     'mandados_express',  'Mandados Express',            'Recados y entregas rápidas',          '🛵', 100,  23),  ('especializados', 'electricista', 'Electricista',                'Cortocircuitos, paneles y cableado','⚡', 500,  30),  ('especializados', 'plomeria',     'Plomería y Tuberías',         'Fugas, sanitarios y drenajes',      '🔧', 500,  31),  ('especializados', 'linea_blanca', 'Reparación de Línea Blanca',  'Refrigeradoras, lavadoras y cocinas','🧊', 500, 32),  ('limpieza',  'alfombra_institucional', 'Limpieza de Alfombra Institucional', 'Oficinas y centros comerciales', '🏢', 1800, 40),  ('limpieza',  'fumigacion',        'Fumigación',                  'Control de plagas certificado',     '🪲', 1200, 41),  ('hogar',     'conserjeria_contrato', 'Conserjería por Contrato',  'Servicio mensual fijo para empresas','📋', 2500, 42)) AS v(cat_slug, slug, name, description, icon, price, ord)JOIN service_categories c ON c.slug = v.cat_slugON CONFLICT (category_id, slug) DO UPDATE SET  name = EXCLUDED.name,  description = EXCLUDED.description,  icon = EXCLUDED.icon,  suggested_price = EXCLUDED.suggested_price,  sort_order = EXCLUDED.sort_order,  is_active = TRUE;-- Desactivar slugs legacy reemplazados por sub-opcionesUPDATE service_types SET is_active = FALSEWHERE slug IN ('mantenimiento_ac');